begin
  new.updated_at = now();
  return new;
end;
$$;

-- profiles: one row per user.
create table public.profiles (
  user_id text primary key not null default public.current_user_id(),
  level text check (level in ('A1', 'A2', 'B1', 'B2')),
  display_name text,
  settings jsonb not null default '{}',
